package com.example.rokidgeminisecretary;
import android.content.*;import android.view.*;import android.widget.*;import android.os.*;import android.graphics.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class PhoneFoldSectionChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("settings card "+n);}
 public static int run(Context base)throws Exception {AtomicReference<Throwable> failure=new AtomicReference<>();CountDownLatch done=new CountDownLatch(1);new Handler(Looper.getMainLooper()).post(()->{try{Context c=new android.view.ContextThemeWrapper(base,android.R.style.Theme_Material_Light);LinearLayout page=PhoneWorkspaceLayout.panel(c);page.setBackgroundColor(Color.rgb(246,248,251));PhoneWorkspaceLayout.heading(c,page,"設定","接続や動作を調整します。");LinearLayout connection=PhoneWorkspaceLayout.panel(c);PhoneWorkspaceLayout.heading(c,connection,"タブレット・PCとの接続","会話・写真・操作をブラウザーで共有できます。");Button connect=new Button(c);connect.setText("タブレット・PCを接続する（QR・再接続）");connect.setTextColor(Color.WHITE);connect.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(24,85,153)));connection.addView(connect,new LinearLayout.LayoutParams(-1,-2));page.addView(connection);EditText draft=new EditText(c);draft.setText("まだ保存していない設定");draft.setSelection(2,5);PhoneFoldSection first=new PhoneFoldSection(c,"接続・音声・読み上げ",PhoneFoldSection.description("接続・音声・読み上げ"),draft);TextView other=new TextView(c);other.setText("追加の設定");PhoneFoldSection second=new PhoneFoldSection(c,"自動で話す（TOPIC）",PhoneFoldSection.description("自動で話す（TOPIC）"),other);page.addView(first);page.addView(second);ok(!first.isOpen()&&draft.getVisibility()==View.GONE);ok(first.heading().getText().toString().contains("閉じています"));ViewParent parent=draft.getParent();first.heading().performClick();ok(first.isOpen()&&draft.getVisibility()==View.VISIBLE);ok(first.heading().getText().toString().contains("開いています"));second.setOpen(true);ok(first.isOpen()&&second.isOpen());for(int i=0;i<20;i++){first.setOpen(i%2==0);ok(draft.getText().toString().equals("まだ保存していない設定"));ok(draft.getSelectionStart()==2&&draft.getSelectionEnd()==5);ok(draft.getParent()==parent);}first.setOpen(true);second.setOpen(false);ok(first.heading().getContentDescription().toString().contains("展開中"));float density=c.getResources().getDisplayMetrics().density;int width=Math.round(360*density);page.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));page.layout(0,0,width,page.getMeasuredHeight());ok(first.heading().getLayout()!=null);ok(first.heading().getLayout().getHeight()+first.heading().getCompoundPaddingTop()+first.heading().getCompoundPaddingBottom()<=first.heading().getHeight());MainActivity owner=new MainActivity();java.lang.reflect.Method attach=ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,c);TextView advanced=new TextView(c);LinearLayout separate=PhoneWorkspaceLayout.panel(c);java.lang.reflect.Method add=MainActivity.class.getDeclaredMethod("addPhoneFoldSection",LinearLayout.class,String.class,View.class);add.setAccessible(true);add.invoke(owner,separate,"詳細設定（API・接続操作）",advanced);java.lang.reflect.Field current=MainActivity.class.getDeclaredField("phoneAdvancedContent");current.setAccessible(true);current.set(owner,advanced);owner.homeAdvanced();ok(advanced.getVisibility()==View.VISIBLE);PhoneFoldSection opened=(PhoneFoldSection)separate.getChildAt(0);ok(opened.isOpen());ok(opened.heading().getText().toString().contains("開いています"));Bitmap image=Bitmap.createBitmap(width,page.getHeight(),Bitmap.Config.ARGB_8888);page.draw(new Canvas(image));try(FileOutputStream stream=new FileOutputStream(new File(base.getFilesDir(),"settings-cards.png"))){image.compress(Bitmap.CompressFormat.PNG,100,stream);}image.recycle();}catch(Throwable e){failure.set(e);}finally{done.countDown();}});if(!done.await(20,TimeUnit.SECONDS))throw new AssertionError("UI deadline");if(failure.get()!=null)throw new AssertionError(failure.get());return n;}
}
